#!/bin/bash
IFS=. read -r i1 i2 i3 i4 <<< "$1"; mask=$(( $2 == 0 ? 0 : 0xffffffff << (32 - $2) )); m1=$(( (mask >> 24) & 255 )); m2=$(( (mask >> 16) & 255 )); m3=$(( (mask >> 8) & 255 )); m4=$(( mask & 255 )); n1=$(( i1 & m1 )); n2=$(( i2 & m2 )); n3=$(( i3 & m3 )); n4=$(( i4 & m4 )); b1=$(( n1 | (255 - m1) )); b2=$(( n2 | (255 - m2) )); b3=$(( n3 | (255 - m3) )); b4=$(( n4 | (255 - m4) )); printf "%d.%d.%d.%d - %d.%d.%d.%d" $n1 $n2 $n3 $((n4 + 1)) $b1 $b2 $b3 $((b4 - 1))
